var INTRO_B64  = "";
  var GATE_B64   = "";
  var PORTAL_B64 = "";

  function b64ToUtf8(b64){
    var bytes = Uint8Array.from(atob(b64), function(c){ return c.charCodeAt(0); });
    return new TextDecoder('utf-8').decode(bytes);
  }

  var introEl = document.getElementById('stageIntro');
  var loginEl = document.getElementById('stageLogin');
  var gateEl  = document.getElementById('stageGate');
  var loadingOverlay = document.getElementById('loadingOverlay');

  // Using srcdoc (instead of a data: URL) keeps each frame same-origin with this page,
  // so localStorage, fetch() (the Google Sheet sync) and postMessage all behave normally.
  introEl.srcdoc  = b64ToUtf8(INTRO_B64);
  loginEl.srcdoc  = b64ToUtf8(PORTAL_B64);
  gateEl.srcdoc   = b64ToUtf8(GATE_B64);

  introEl.addEventListener('load', function(){
    loadingOverlay.classList.add('hide');
  });

  window.addEventListener('message', function(e){
    var msg = e.data;

    if(msg === 'studint:introDone'){
      introEl.style.display = 'none';
      loginEl.style.display = 'block';
    }

    else if(msg === 'studint:loginSuccess'){
      loginEl.style.display = 'none';
      gateEl.style.display = 'block';
    }

    else if(msg === 'studint:gateEnter'){
      gateEl.style.display = 'none';
      loginEl.style.display = 'block';
      // tell the portal frame it's clear to reveal the app (Payment tab, or Profile if not set yet)
      loginEl.contentWindow.postMessage('studint:proceed', '*');
    }
  });